<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue';import PageHeader from '@/components/PageHeader.vue';import { adminApi } from '@/api/admin';import type { AuditEvent } from '@/types/admin'
const items=ref<AuditEvent[]>([]),total=ref(0),loading=ref(false);const query=reactive({search:'',action:'',outcome:'',page:1,pageSize:20})
async function load(){loading.value=true;try{const r=await adminApi.audit(query);items.value=r.items;total.value=r.total}finally{loading.value=false}}onMounted(load)
</script>
<template><PageHeader title="操作审计" description="普通描述与请求级技术字段放在同一条不可变审计事件中。"/><div class="panel"><div class="toolbar"><el-input v-model="query.search" clearable placeholder="账号 / 资源 / Request ID" style="width:280px"/><el-input v-model="query.action" clearable placeholder="action_name" style="width:210px"/><el-select v-model="query.outcome" clearable placeholder="结果" style="width:130px"><el-option label="成功" value="success"/><el-option label="失败" value="failure"/></el-select><el-button type="primary" @click="query.page=1;load()">查询</el-button></div><el-table :data="items" v-loading="loading"><el-table-column prop="createdAt" label="时间" width="190"/><el-table-column prop="action" label="操作" width="220"><template #default="s"><span class="technical">{{s.row.action}}</span></template></el-table-column><el-table-column prop="actorId" label="操作者" min-width="250"/><el-table-column label="资源" min-width="230"><template #default="s">{{s.row.resourceType}} / <span class="technical">{{s.row.resourceId}}</span></template></el-table-column><el-table-column prop="outcome" label="结果" width="90"><template #default="s"><el-tag :type="s.row.outcome==='success'?'success':'danger'">{{s.row.outcome}}</el-tag></template></el-table-column><el-table-column prop="requestId" label="Request ID" min-width="220"/></el-table><el-pagination v-model:current-page="query.page" v-model:page-size="query.pageSize" :total="total" layout="total, prev, pager, next" style="margin-top:16px" @current-change="load"/></div></template>
